// Syllable counting for English, tuned against CMUdict.
//
// Two layers:
//   1. an exception table, generated by tools/build-dict.mjs, holding every
//      CMUdict word the heuristic below gets wrong (loadExceptions);
//   2. the heuristic itself, used for anything out of dictionary.
//
// The heuristic lives here rather than in the build script so there is exactly
// one implementation: the table is defined as "wherever this function is wrong".

const LETTER_NAME_SYLLABLES = {
  a: 1, b: 1, c: 1, d: 1, e: 1, f: 1, g: 1, h: 2, i: 1, j: 1, k: 1, l: 1,
  m: 1, n: 1, o: 1, p: 1, q: 1, r: 1, s: 1, t: 1, u: 1, v: 1, w: 3, x: 1,
  y: 2, z: 1,
};

// Rewrites applied before counting vowel groups. Two moves only: delete letters
// to merge two written vowels into one spoken nucleus, or splice a 'z' between
// them to force a split. Order matters — the longest, most specific first.
const REWRITES = [
  // -- merges --------------------------------------------------------------
  [/[st]ion/g, 'shan'],            // ambition, mission -> one nucleus
  [/[ct]ia([ln])/g, 'sha$1'],      // special, martial
  [/[ct]iou|[ct]eou|giou|geou/g, 'shu'], // gracious, gorgeous
  [/eau/g, 'o'],                   // bureau, archambeau
  [/ough/g, 'o'],                  // though, thorough is an exception
  [/aigh|eigh/g, 'ay'],            // straight, eight
  [/([^aeiou])ae/g, '$1e'],        // aerobic, michael
  [/^ae/g, 'e'],                   // aerial, aesthetic
  [/qu/g, 'kw'],
  // -- splits --------------------------------------------------------------
  [/([aeiouy])(ing|ish|est)$/g, '$1z$2'], // agreeing, accruing, flying, bluish
  [/([^aeiouy])ie(r|rs|st|d|s)$/g, '$1izhe$2'], // abshier, amplifiers
  [/uism|uist/g, 'uzism'],
  [/ire/g, 'izre'],                // fire, acquirer, desire  ("ire" is two)
  [/([aeiou])ye/g, '$1yze'],       // ayers, meyer, buyer, lawyer
  [/i([aou])/g, 'iz$1'],           // riot, media, triumph
  [/u([aeo])/g, 'uz$1'],           // dual, fluent, duo
];

const SIBILANT = /(?:[sxz]|ch|sh|ss|tch|c|g|o)$/;

/**
 * Heuristic syllable count for a bare alphabetic token.
 * Never returns less than 1 for a non-empty token.
 */
export function guessSyllables(raw) {
  let w = String(raw).toLowerCase().replace(/[^a-z]/g, '');
  if (!w) return 0;
  if (w.length <= 2) return 1;

  // -- recursive endings -----------------------------------------------------
  // These are stripped before anything else so the stem is judged on its own.
  if (w.length > 4 && w.endsWith('ically')) return guessSyllables(w.slice(0, -4)) + 1;
  if (w.length > 4 && /(?:ly|ness|ment|ful|less|able|ible|hood|ship|like)$/.test(w)) {
    const suffix = /(?:ness|ment|able|ible|hood|ship|like|less|ful|ly)$/.exec(w)[0];
    const stem = w.slice(0, -suffix.length);
    if (stem.length > 2) {
      const own = suffix === 'ly' || suffix === 'ful' ? 1 : suffix.length > 4 ? 2 : 1;
      return guessSyllables(stem) + (suffix === 'able' || suffix === 'ible' ? 2 : own);
    }
  }
  if (w.length > 3 && w.endsWith('es')) {
    const stem = w.slice(0, -2);
    if (SIBILANT.test(stem)) return guessSyllables(stem) + 1;
    return guessSyllables(w.slice(0, -1));
  }
  if (w.length > 3 && w.endsWith('s') && !/(?:ss|us|is|as|os)$/.test(w)) {
    return guessSyllables(w.slice(0, -1));
  }
  if (w.length > 3 && w.endsWith('ed')) {
    const stem = w.slice(0, -2);
    if (/[td]$/.test(stem)) return guessSyllables(stem) + 1;
    return guessSyllables(stem + 'e'); // addled -> addle, fired -> fire
  }

  // -- final e ---------------------------------------------------------------
  // Silent, except that a consonant + l/r before it is syllabic: table, acre.
  if (w.length > 3 && w.endsWith('e')) {
    const stem = w.slice(0, -1);
    const syllabic = /[^aeiouylr][lr]$/.test(stem) || /[^aeiouy]ir$/.test(stem);
    return countGroups(stem) + (syllabic ? 1 : 0);
  }

  return countGroups(w);
}

function countGroups(w) {
  for (const [re, to] of REWRITES) w = w.replace(re, to);
  let count = (w.match(/[aeiouy]+/g) || []).length;
  // "-ism", "-asm" carry a beat of their own: prism, sarcasm
  if (/[^aeiouy](?:ism|asm)$/.test(w)) count++;
  // a lone trailing y after a consonant cluster is still a nucleus; a word that
  // rewrote down to nothing is still spoken.
  return count < 1 ? 1 : count;
}

/**
 * Number of syllables in the spoken name of an acronym, e.g. "HTML" -> 4.
 */
export function acronymSyllables(token) {
  let n = 0;
  for (const ch of token.toLowerCase()) {
    n += LETTER_NAME_SYLLABLES[ch] ?? 1;
  }
  return n;
}

// ---------------------------------------------------------------------------
// Numbers
// ---------------------------------------------------------------------------

const ONES = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven',
  'eight', 'nine', 'ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen',
  'sixteen', 'seventeen', 'eighteen', 'nineteen'];
const TENS = ['', '', 'twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy',
  'eighty', 'ninety'];
const SCALES = [[1e9, 'billion'], [1e6, 'million'], [1e3, 'thousand'], [100, 'hundred']];

const ORDINAL = {
  one: 'first', two: 'second', three: 'third', five: 'fifth', eight: 'eighth',
  nine: 'ninth', twelve: 'twelfth',
};

/** Spell an integer as words. Returns an array of word tokens. */
export function numberToWords(n) {
  if (!Number.isFinite(n)) return [];
  if (n < 0) return ['negative', ...numberToWords(-n)];
  n = Math.floor(n);
  if (n < 20) return [ONES[n]];
  if (n < 100) {
    const t = TENS[Math.floor(n / 10)];
    const r = n % 10;
    return r ? [t, ONES[r]] : [t];
  }
  for (const [value, name] of SCALES) {
    if (n >= value) {
      const head = numberToWords(Math.floor(n / value));
      const rest = n % value;
      return [...head, name, ...(rest ? numberToWords(rest) : [])];
    }
  }
  return [ONES[n]];
}

/** Turn a numeric literal into spoken word tokens ("1984" -> nineteen eighty four). */
export function numericTokens(literal) {
  const grouped = /\d,\d/.test(String(literal)); // "1,250" is a quantity, not a year
  const cleaned = String(literal).replace(/,/g, '');
  const ordinal = /^(\d+)(st|nd|rd|th)$/i.exec(cleaned);
  if (ordinal) {
    const words = numberToWords(Number(ordinal[1]));
    const last = words[words.length - 1];
    words[words.length - 1] = ORDINAL[last] || (last.endsWith('y') ? last.slice(0, -1) + 'ieth' : last + 'th');
    return words;
  }
  const decimal = /^(\d*)\.(\d+)$/.exec(cleaned);
  if (decimal) {
    const head = decimal[1] ? numberToWords(Number(decimal[1])) : ['zero'];
    return [...head, 'point', ...decimal[2].split('').map((d) => ONES[Number(d)])];
  }
  if (!/^\d+$/.test(cleaned)) {
    // mixed junk like "3x" — read the digits, keep the rest for the heuristic
    return cleaned.split(/(\d+)/).filter(Boolean).flatMap((p) => (/^\d+$/.test(p) ? numericTokens(p) : [p]));
  }
  const n = Number(cleaned);
  // Four-digit years are read in pairs: 1984, 2026 — but not 2000-2009.
  if (!grouped && cleaned.length === 4 && n >= 1100 && n <= 2099 && !(n >= 2000 && n <= 2009)) {
    const hi = Math.floor(n / 100);
    const lo = n % 100;
    if (lo === 0) return [...numberToWords(hi), 'hundred'];
    if (lo < 10) return [...numberToWords(hi), 'oh', ONES[lo]];
    return [...numberToWords(hi), ...numberToWords(lo)];
  }
  if (cleaned.length > 12) return cleaned.split('').map((d) => ONES[Number(d)]);
  return numberToWords(n);
}

// ---------------------------------------------------------------------------
// Dictionary
// ---------------------------------------------------------------------------

/**
 * Decode the front-coded exception table produced by tools/build-dict.mjs.
 * Each line is: <sharedPrefixLength base36><suffix>\t<counts joined by ",">
 */
export function decodeExceptions(text) {
  const map = new Map();
  let prev = '';
  for (const line of text.split('\n')) {
    if (!line) continue;
    const tab = line.indexOf('\t');
    if (tab < 0) continue;
    const shared = parseInt(line[0], 36);
    const word = prev.slice(0, shared) + line.slice(1, tab);
    prev = word;
    const counts = line.slice(tab + 1).split(',').map(Number);
    map.set(word, counts);
  }
  return map;
}

/**
 * Basic text normalization for one token: compose Unicode, fold the several
 * curly apostrophes and hyphens onto their ASCII forms, drop zero-width marks.
 * Without this, "don’t" as typed by a word processor misses the dictionary.
 */
export function normalize(token) {
  return String(token)
    .normalize('NFKC')
    // curly and modifier apostrophes -> ASCII '
    .replace(/[‘’ʼ՚＇]/g, "'")
    // hyphens, dashes and the minus sign -> ASCII -
    .replace(/[‐‑‒–—−]/g, '-')
    // zero-width marks and the soft hyphen carry no sound at all
    .replace(/[​-‏⁠﻿­]/g, '');
}

export class SyllableCounter {
  constructor(exceptions = new Map()) {
    this.exceptions = exceptions;
    this.cache = new Map();
  }

  static async load(url) {
    const res = await fetch(url);
    if (!res.ok) throw new Error(`syllable table: HTTP ${res.status}`);
    return new SyllableCounter(decodeExceptions(await res.text()));
  }

  get size() {
    return this.exceptions.size;
  }

  /**
   * Possible syllable counts for one already-normalized token, plus provenance.
   * Returns { counts: number[], source: 'dict'|'guess'|'acronym'|'number' }.
   */
  analyze(token) {
    const hit = this.cache.get(token);
    if (hit) return hit;
    const out = this.#analyze(normalize(token));
    this.cache.set(token, out);
    return out;
  }

  #analyze(token) {
    if (/\d/.test(token)) {
      const words = numericTokens(token);
      let total = 0;
      for (const w of words) total += this.analyze(w).counts[0];
      return { counts: [total], source: 'number' };
    }

    const key = token.toLowerCase();
    const known = this.exceptions.get(key);
    if (known) return { counts: known, source: 'dict' };

    // hyphenates, slashed pairs and dotted names ("well-worn", "and/or",
    // "toni.bsky.team"): sum the parts, which are each spoken separately
    if (/[-\/.]/.test(token)) {
      const parts = token.split(/[-\/.]+/).filter(Boolean);
      if (parts.length > 1) {
        let total = 0;
        let source = 'dict';
        for (const p of parts) {
          const a = this.analyze(p);
          total += a.counts[0];
          if (a.source !== 'dict') source = 'guess';
        }
        return { counts: [total], source };
      }
    }

    // possessives and contractions the table may not hold
    const stripped = key.replace(/[^a-z']/g, '');
    if (stripped !== key && stripped) return this.analyze(stripped);

    const base = /^(.+?)'s$/.exec(stripped);
    if (base) {
      const inner = this.exceptions.get(base[1]);
      if (inner) {
        const extra = /(?:[sxz]|ch|sh|ge|ce)$/.test(base[1]) ? 1 : 0;
        return { counts: inner.map((c) => c + extra), source: 'dict' };
      }
    }

    // ALL-CAPS with no dictionary entry reads as letters ("HTML", "NASA" is in dict)
    if (/^[A-Z]{2,5}$/.test(token) && !/^[AEIOUY]*$/.test(token)) {
      const vowelless = !/[AEIOUY]/.test(token);
      if (vowelless || token.length <= 3) {
        return { counts: [acronymSyllables(token)], source: 'acronym' };
      }
    }

    return { counts: [guessSyllables(stripped || key)], source: 'guess' };
  }

  /** Primary (most likely) syllable count. */
  count(token) {
    return this.analyze(token).counts[0];
  }
}
